    "privacy.localStorageText": "게임 진행 상황, 통계 및 환경설정(테마, 색상 구성, 애니메이션 설정)은 브라우저 localStorage를 사용하여 기기에 로컬로 저장됩니다. 이 데이터는 기기를 절대 떠나지 않습니다.",
    "privacy.advertisingTitle": "광고",
    "privacy.advertisingText": "Inventle은 타사 광고 네트워크(예: Google AdSense)를 통해 광고를 표시할 수 있습니다. 이러한 네트워크는 브라우징 활동을 기반으로 광고를 제공하기 위해 쿠키를 사용할 수 있습니다. 브라우저 설정을 통해 쿠키 환경설정을 관리할 수 있습니다.",
    "privacy.dataSharingTitle": "데이터 공유",
    "privacy.dataSharingText": "위에 설명된 광고 네트워크 통합에 필요한 경우를 제외하고 수집된 데이터를 제3자에게 <strong style=\"color:var(--text)\">판매, 거래 또는 공유하지 않습니다</strong>.",
