    "about.whatIs": "Inventle이란?",
    "about.whatIsText": "Wordle에서 영감을 받은 일일 발명 추측 게임입니다. 매일 역사적 발명품이 주어지고, 그것이 만들어진 연도를 6번 안에 맞춰야 합니다. 색상이 있는 숫자가 정답으로 안내합니다: 초록색은 정확, 호박색은 1 차이, 회색은 2 이상 차이를 뜻합니다.",
    "about.howItWorks": "플레이 방식",
    "about.howItWorksText": "메인 라운드 후 보너스 라운드에서 발명의 원산국과 발명가를 맞추는 도전이 이어집니다. 통계를 추적하고, 연속 기록을 세우고, 결과를 친구들과 공유하세요.",
    "about.database": "데이터베이스",
    "about.databaseText": "Inventle에는 바퀴와 쟁기 같은 고대 도구부터 CRISPR과 SpaceX의 재사용 로켓 같은 현대 혁신까지, 수천 년의 인류 역사에 걸친 773개의 발명품이 수록되어 있습니다. 새로운 퍼즐이 매일 교체됩니다.",
    "about.whyBuilt": "만든 이유",
    "about.whyBuiltText": "혁신의 역사에 대해 가르쳐주는 재미있고 교육적인 게임을 만들고 싶었습니다. 모든 퍼즐이 작은 역사 수업입니다. 계정도 필요 없고, 데이터도 수집하지 않습니다. 그냥 플레이하세요.",
