    "terms.acceptanceText": "Inventle(\"게임\")에 접속하거나 사용함으로써 귀하는 본 이용약관에 동의하게 됩니다. 동의하지 않으시면 게임을 사용하지 마세요.",
    "terms.description": "서비스 설명",
    "terms.descriptionText": "Inventle은 무료 브라우저 기반 일일 추측 게임입니다. 게임은 어떠한 종류의 보증도 없이 \"있는 그대로\" 제공됩니다.",
    "terms.fairPlay": "페어 플레이",
    "terms.fairPlayText1": "여기에 엄격한 규칙은 없습니다 — 캐주얼 게임이니까요. 답을 검색하거나 도구를 사용해도 되지만, 그러면 스스로의 재미를 빼앗는 것입니다. 핵심은 도전입니다!",
    "terms.fairPlayText2": "다만, 다른 사람들의 게임을 망치거나 서버를 방해하는 행위는 하지 말아 주세요.",
    "terms.dataPrivacy": "데이터 및 개인정보",
    "terms.dataPrivacyText": "게임 사용은 <a href=\"privacy.html\">개인정보 처리방침</a>에도 적용됩니다. Inventle은 익명 게임 통계만 수집합니다. 개인 데이터는 수집되거나 저장되지 않습니다.",
    "terms.availability": "서비스 가용성",
    "terms.availabilityText": "Inventle을 24시간 연중무휴로 운영하는 것이 목표이지만, 중단 없는 접속이 보장되지는 않습니다. 유지보수나 업데이트를 위해 일시적으로 서비스가 중단될 수 있습니다.",
    "terms.liability": "책임 제한",
