    "privacy.ipText": "<strong style=\"color:var(--text)\">Nigdy nie przechowujemy adresów IP</strong>. Gdy statystyki gry są przesyłane, usługa geolokalizacji zewnętrzna określa przybliżony kraj na podstawie Twojego IP. IP jest przetwarzane wyłącznie w trakcie przesyłu i <strong style=\"color:var(--text)\">nigdy nie jest logowane, zapisywane ani rejestrowane</strong> przez Inventle w żadnej formie. Nie mamy możliwości identyfikacji, śledzenia ani ponownej identyfikacji żadnego gracza. Wszystkie przechowywane dane są w pełni anonimowe i nie mogą być powiązane z żadną osobą ani urządzeniem.",
    "privacy.localStorageTitle": "Pamięć lokalna",
    "privacy.localStorageText": "Postęp gry, statystyki i preferencje (motyw, schemat kolorów, ustawienia animacji) są przechowywane lokalnie na Twoim urządzeniu za pomocą localStorage przeglądarki. Te dane nigdy nie opuszczają Twojego urządzenia.",
    "privacy.advertisingTitle": "Reklamy",
    "privacy.advertisingText": "Inventle może wyświetlać reklamy za pośrednictwem zewnętrznych sieci reklamowych (np. Google AdSense). Sieci te mogą używać ciasteczek do wyświetlania reklam na podstawie Twojej aktywności przeglądania. Możesz zarządzać preferencjami ciasteczek w ustawieniach przeglądarki.",
    "privacy.dataSharingTitle": "Udostępnianie danych",
