    "about.whatIs": "Czym jest Inventle?",
    "about.whatIsText": "Codzienna gra w zgadywanie wynalazków, inspirowana Wordle. Każdego dnia otrzymujesz historyczny wynalazek i masz 6 prób, aby odgadnąć rok jego powstania. Kolorowe cyfry prowadzą do odpowiedzi: zielony oznacza trafienie, bursztynowy różnicę o 1, szary różnicę o 2 lub więcej.",
    "about.howItWorks": "Jak to działa",
