    "about.database": "Baza danych",
    "about.databaseText": "Inventle zawiera 773 wynalazki obejmujące tysiące lat ludzkiej historii — od starożytnych narzędzi jak koło i pług po nowoczesne innowacje jak CRISPR i rakiety wielokrotnego użytku SpaceX. Nowe zagadki codziennie.",
    "about.whyBuilt": "Dlaczego to zbudowałem",
