    "terms.fairPlay": "Fair play",
    "terms.fairPlayText1": "Nie ma tu ścisłych reguł — to casualowa gra. Możesz szukać odpowiedzi lub używać narzędzi, ale zepsujesz sobie tylko zabawę. Chodzi o wyzwanie!",
    "terms.fairPlayText2": "Prosimy jednak, aby nie robić niczego, co zepsuje grę innym lub zakłóci działanie serwerów.",
    "terms.dataPrivacy": "Dane i prywatność",
    "terms.dataPrivacyText": "Korzystanie z Gry podlega również <a href=\"privacy.html\">Polityce Prywatności</a>. Inventle zbiera wyłącznie anonimowe statystyki gry. Żadne dane osobowe nie są zbierane ani przechowywane.",
    "terms.availability": "Dostępność",
