    "about.whatIs": "Was ist Inventle?",
    "about.whatIsText": "Ein tägliches Erfindungs-Ratespiel, inspiriert von Wordle. Jeden Tag erhältst du eine historische Erfindung und hast 6 Versuche, das Entstehungsjahr zu erraten. Farbige Ziffern leiten dich zur Antwort: Grün bedeutet exakt, Bernstein bedeutet Abweichung um 1, Grau bedeutet Abweichung um 2 oder mehr.",
    "about.howItWorks": "So funktioniert es",
    "about.howItWorksText": "Nach der Hauptrunde fordern dich Bonusrunden heraus, das Herkunftsland und den Erfinder zu erraten. Verfolge deine Statistiken, baue deine Serie auf und teile deine Ergebnisse mit Freunden.",
    "about.database": "Die Datenbank",
    "about.databaseText": "Inventle enthält 773 Erfindungen aus Tausenden Jahren Menschheitsgeschichte — von antiken Werkzeugen wie dem Rad und dem Pflug bis hin zu modernen Innovationen wie CRISPR und den wiederverwendbaren Raketen von SpaceX. Täglich neue Rätsel.",
    "about.whyBuilt": "Warum ich es gebaut habe",
