    "terms.fairPlay": "Fairplay",
    "terms.fairPlayText1": "Es gibt keine strengen Regeln — es ist ein Casual-Spiel. Du kannst Antworten nachschlagen oder Tools verwenden, aber du verdirbst dir nur selbst den Spaß. Es geht um die Herausforderung!",
    "terms.fairPlayText2": "Bitte tue jedoch nichts, was das Spiel für andere kaputt macht oder die Server stört.",
