    "about.whatIs": "Inventle क्या है?",
    "about.whatIsText": "Wordle से प्रेरित एक दैनिक आविष्कार अनुमान खेल। हर दिन एक ऐतिहासिक आविष्कार दिया जाता है और आपके पास इसके निर्माण वर्ष का अनुमान लगाने के 6 मौके होते हैं। रंगीन अंक मार्गदर्शन करते हैं: हरा मतलब सटीक, पीला मतलब 1 का अंतर, स्लेटी मतलब 2 या अधिक का अंतर।",
    "about.howItWorks": "कैसे काम करता है",
