    "about.database": "डेटाबेस",
    "about.databaseText": "Inventle में 773 आविष्कार हैं जो हज़ारों वर्षों के मानव इतिहास में फैले हैं — पहिये और हल जैसे प्राचीन उपकरणों से लेकर CRISPR और SpaceX के पुन: प्रयोज्य रॉकेटों जैसी आधुनिक नवाचारों तक। हर दिन नई पहेली।",
    "about.whyBuilt": "मैंने इसे क्यों बनाया",
    "about.whyBuiltText": "मैं एक मज़ेदार, शैक्षिक खेल बनाना चाहता था जो लोगों को नवाचार का इतिहास सिखाए। हर पहेली एक मिनी इतिहास पाठ है। कोई खाता आवश्यक नहीं, कोई डेटा संग्रह नहीं, बस खेलें।",
    "about.support": "सहायता",
