    "terms.title": "सेवा की शर्तें",
    "terms.lastUpdated": "अंतिम अपडेट: अप्रैल 2026",
    "terms.acceptance": "शर्तों की स्वीकृति",
    "terms.acceptanceText": "Inventle (\"खेल\") का उपयोग करके, आप इन सेवा शर्तों से बाध्य होने के लिए सहमत होते हैं। यदि आप सहमत नहीं हैं, तो कृपया खेल का उपयोग न करें।",
    "terms.description": "सेवा का विवरण",
    "terms.descriptionText": "Inventle एक मुफ़्त, ब्राउज़र-आधारित दैनिक अनुमान खेल है। खेल \"जैसा है\" प्रदान किया जाता है बिना किसी गारंटी के।",
    "terms.fairPlay": "निष्पक्ष खेल",
    "terms.fairPlayText1": "यहाँ कोई सख्त नियम नहीं हैं — यह एक आरामदायक खेल है। आप उत्तर खोज सकते हैं या उपकरण इस्तेमाल कर सकते हैं, लेकिन इससे आप अपना ही मज़ा खराब करेंगे। मुद्दा चुनौती है!",
    "terms.fairPlayText2": "लेकिन कृपया ऐसा कुछ न करें जो दूसरों के खेल को खराब करे या सर्वर में बाधा डाले।",
    "terms.dataPrivacy": "डेटा और गोपनीयता",
    "terms.dataPrivacyText": "खेल का आपका उपयोग <a href=\"privacy.html\">गोपनीयता नीति</a> द्वारा भी शासित होता है। Inventle केवल गुमनाम गेमप्ले आँकड़े एकत्र करता है। कोई व्यक्तिगत डेटा एकत्र या संग्रहीत नहीं किया जाता।",
    "terms.availability": "उपलब्धता",
    "terms.availabilityText": "लक्ष्य Inventle को 24/7 उपलब्ध रखना है, लेकिन निर्बाध पहुँच की गारंटी नहीं है। रखरखाव या अपडेट के लिए खेल अस्थायी रूप से अनुपलब्ध हो सकता है।",
    "terms.liability": "दायित्व की सीमा",
    "terms.liabilityText": "Inventle और इसके निर्माता खेल के उपयोग से उत्पन्न किसी भी क्षति के लिए उत्तरदायी नहीं होंगे।",
    "terms.modifications": "संशोधन",
