    // About modal (index.html)
    "aboutModal.intro": "Inventle एक दैनिक अनुमान खेल है जिसमें आपको यह पता लगाना होता है कि कोई आविष्कार किस वर्ष बना था। Wordle जैसा, लेकिन इतिहास प्रेमियों के लिए।",
    "aboutModal.gameplay": "हर दिन एक नया आविष्कार आता है। आपको <strong style=\"color:var(--text)\">6 अनुमान</strong> मिलते हैं, और रंगीन अंक आपको सही उत्तर की ओर मार्गदर्शन करते हैं। मुख्य राउंड के बाद, <strong style=\"color:var(--text)\">देश</strong> और <strong style=\"color:var(--text)\">आविष्कारक</strong> के बोनस राउंड में अपना ज्ञान परखें।",
    "aboutModal.database": "डेटाबेस में प्राचीन इतिहास से लेकर आधुनिक युग तक <strong style=\"color:var(--text)\">773 आविष्कार</strong> हैं। हर दिन एक नई पहेली के लिए वापस आएं।",
    "aboutModal.madeBy": "बनाया गया",
    "aboutModal.builtWith": "शुद्ध HTML, CSS और JavaScript से बनाया गया। कोई फ्रेमवर्क नहीं, कोई बिल्ड टूल नहीं, बस वाइब्स।"
